// Extraer archivo, generar Hash SHA-256 y validar duplicados
const crypto = require('crypto');

const items = $input.all();
const configRows = $('Supabase - Leer app_settings').all();

let limite = 20.0;
let correoDefecto = 'andrescassiani46@gmail.com';
let modoEnvio = 'AUTOMATICO';

for (const r of configRows) {
  if (r.json.clave === 'tmo_limite_segundos') limite = parseFloat(r.json.valor_numerico);
  if (r.json.clave === 'correo_destinatario_defecto') correoDefecto = r.json.valor_texto;
  if (r.json.clave === 'modo_envio') modoEnvio = r.json.valor_texto;
}

const inputData = items[0].json;
const binaryData = items[0].binary;

let fileContent = '';
if (binaryData && binaryData.data) {
  fileContent = binaryData.data.data || '';
} else {
  fileContent = JSON.stringify(inputData);
}

const hashSha256 = crypto.createHash('sha256').update(fileContent).digest('hex');

return [{
  json: {
    hash_sha256: hashSha256,
    nombre_archivo: (binaryData && binaryData.data && binaryData.data.fileName) || 'gestiones_tmo.xlsx',
    correo_destinatario: inputData.correo_destinatario || correoDefecto,
    limite_tmo: limite,
    modo_envio: modoEnvio,
    registros_crudos: inputData.agentes || inputData.operaciones || []
  },
  binary: binaryData
}];

// Código de procesamiento en lote / Looping
// Fórmula: TMO promedio = Suma / Gestiones válidas
// Porcentaje del límite = (TMO promedio / Límite) * 100

const prev = $('Validar Archivo & Hash SHA-256').first().json;
const threshold = prev.limite_tmo || 20.0;
const rawRows = prev.registros_crudos;

const agentMap = {};
let totalFilas = 0;
let validas = 0;
let invalidas = 0;

for (const r of rawRows) {
  totalFilas++;
  const name = (r.operador || r.agente || r.nombre || '').toString().trim();
  const tmo = parseFloat(r.tmo || r.tiempo_gestion_segundos || r.tiempo);

  if (!name || isNaN(tmo) || tmo < 0) {
    invalidas++;
    continue;
  }
  validas++;
  if (!agentMap[name]) {
    agentMap[name] = { name, count: 0, sum: 0 };
  }
  agentMap[name].count += (r.operaciones || 1);
  agentMap[name].sum += (tmo * (r.operaciones || 1));
}

const summaries = [];
let sumaTotalTmo = 0;
let aprobados = 0;
let revision = 0;

for (const [name, d] of Object.entries(agentMap)) {
  const tmoPromedio = Math.round((d.sum / d.count) * 100) / 100;
  const pctLimite = Math.round((tmoPromedio / threshold) * 10000) / 100;
  const estado = tmoPromedio <= threshold ? 'APROBADO' : 'REQUIERE REVISIÓN';

  if (estado === 'APROBADO') aprobados++; else revision++;
  sumaTotalTmo += tmoPromedio;

  summaries.push({
    nombre_agente: name,
    gestiones_validas: d.count,
    suma_tiempos_segundos: Math.round(d.sum * 100) / 100,
    tmo_promedio_segundos: tmoPromedio,
    limite_segundos: threshold,
    porcentaje_frente_al_limite: pctLimite,
    clasificacion: estado
  });
}

summaries.sort((a, b) => b.tmo_promedio_segundos - a.tmo_promedio_segundos);
const totalAgentes = summaries.length;
const tmoGlobal = totalAgentes > 0 ? Math.round((sumaTotalTmo / totalAgentes) * 100) / 100 : 0;
const tasaAprobacion = totalAgentes > 0 ? Math.round((aprobados / totalAgentes) * 10000) / 100 : 0;

return [{
  json: {
    run_meta: {
      hash_sha256: prev.hash_sha256,
      nombre_archivo: prev.nombre_archivo,
      total_filas_leidas: totalFilas,
      total_filas_validas: validas,
      total_filas_invalidas: invalidas,
      total_agentes: totalAgentes,
      tmo_global_promedio: tmoGlobal,
      limite_aplicado: threshold,
      agentes_aprobados: aprobados,
      agentes_requiere_revision: revision,
      tasa_aprobacion_pct: tasaAprobacion,
      destinatario_correo: prev.correo_destinatario
    },
    tmo_summaries: summaries
  }
}];
